using System.Reflection;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public class LayerDependencyTests
{
    // Language core only: no I/O, network, persistence or framework assemblies.
    private static readonly string[] LanguageCore =
    [
        "System.Runtime", "System.Private.CoreLib", "netstandard", "mscorlib",
        "System.Collections", "System.Collections.Immutable", "System.Linq",
        "System.Threading", "System.Threading.Tasks", "System.Memory",
        "System.Runtime.Extensions", "System.Diagnostics.CodeAnalysis",
    ];

    [Fact]
    public void Domain_depends_only_on_itself_and_the_language_core() =>
        AssertOnlyDependsOn(typeof(Money).Assembly, []);

    [Fact]
    public void Application_depends_only_on_itself_domain_and_the_language_core() =>
        AssertOnlyDependsOn(typeof(AuthorizePayment).Assembly, [typeof(Money).Assembly.GetName().Name!]);

    private static void AssertOnlyDependsOn(Assembly assembly, string[] innerLayers)
    {
        var allowed = LanguageCore.Append(assembly.GetName().Name!).Concat(innerLayers).ToHashSet();
        var violations = assembly.GetReferencedAssemblies()
            .Select(a => a.Name!)
            .Where(name => !allowed.Contains(name))
            .Order()
            .ToList();

        Assert.True(violations.Count == 0,
            $"Violations in {assembly.GetName().Name}: {string.Join(", ", violations)}");
    }
}
EOF
